package com.andye.warmod.phalanx.network;import com.andye.warmod.WarMod;import java.util.UUID;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;public record ClientboundPhalanxStatePayload(UUID turretId,float yaw,float pitch,float spin,float bloom,int rounds,int status)implements CustomPacketPayload{public static final Type<ClientboundPhalanxStatePayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(WarMod.MOD_ID,"phalanx_state"));public static final StreamCodec<RegistryFriendlyByteBuf,ClientboundPhalanxStatePayload> STREAM_CODEC=StreamCodec.of((b,p)->{b.writeUUID(p.turretId);b.writeFloat(p.yaw);b.writeFloat(p.pitch);b.writeFloat(p.spin);b.writeFloat(p.bloom);b.writeVarInt(p.rounds);b.writeVarInt(p.status);},b->new ClientboundPhalanxStatePayload(b.readUUID(),b.readFloat(),b.readFloat(),b.readFloat(),b.readFloat(),b.readVarInt(),b.readVarInt()));@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
